<style>
.rb-page{font-family:Inter, sans-serif;color:#25313C}.rb-head{display:flex;justify-content:space-between;align-items:flex-start;gap:16px;margin-bottom:22px}.rb-title{font-size:23px;font-weight:700;color:#123B5D;margin:0}.rb-sub{font-size:13px;color:#64748B;margin:6px 0 0}.rb-actions{display:flex;gap:9px;flex-wrap:wrap}.rb-btn{display:inline-flex;align-items:center;justify-content:center;min-height:40px;padding:0 16px;border-radius:9px;border:1px solid #CBD5E1;background:#fff;color:#334155;font-size:13px;font-weight:600;text-decoration:none;cursor:pointer}.rb-btn.primary{background:#123B5D;border-color:#123B5D;color:#fff}.rb-btn.danger{color:#B91C1C;border-color:#FECACA}.rb-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin-bottom:18px}.rb-card,.rb-panel{background:#fff;border:1px solid #CBD5E1;border-radius:15px;padding:18px}.rb-k-label{font-size:12px;color:#64748B;font-weight:600}.rb-k-value{font-size:27px;color:#123B5D;font-weight:700;margin-top:7px}.rb-panel{margin-bottom:16px}.rb-panel h3{font-size:15px;color:#123B5D;margin:0 0 14px;font-weight:700}.rb-table{width:100%;border-collapse:collapse}.rb-table th{text-align:left;background:#F8FAFC;color:#64748B;font-size:11px;font-weight:700;padding:12px 10px}.rb-table td{font-size:13px;padding:13px 10px;border-top:1px solid #E2E8F0;vertical-align:middle}.rb-muted{color:#64748B}.rb-pill{display:inline-block;padding:4px 9px;border-radius:20px;background:#EFF6FF;color:#1D4ED8;font-size:11px;font-weight:700}.rb-pill.green{background:#DCFCE7;color:#166534}.rb-pill.gray{background:#F1F5F9;color:#475569}.rb-form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.rb-field label{display:block;font-size:12px;font-weight:650;color:#334155;margin-bottom:6px}.rb-field input,.rb-field select,.rb-field textarea{width:100%;border:1px solid #CBD5E1;border-radius:9px;padding:10px 12px;font:13px Inter,sans-serif;color:#25313C;background:#fff}.rb-field textarea{min-height:90px}.rb-perm-